import RNA, random, time, multiprocessing as mp, json

unitA = "(((.(((...))).(((....))).)))"
unitB = "(((.(((....))).(((...))).)))"

def worker(args):
    t, seed = args
    random.seed(seed)
    for _ in range(100):
        start = ''.join(random.choice('ACGU') for _ in range(len(t)))
        seq, d = RNA.inverse_fold(start, t)
        if d == 0 and RNA.fold_compound(seq).mfe()[0] == t:
            return seq
    return None

def solve_many(t, n, seeds):
    found = set()
    with mp.Pool(48) as p:
        for r in p.imap_unordered(worker, [(t,s) for s in seeds]):
            if r and r not in found:
                found.add(r)
                if len(found) >= n:
                    p.terminate(); break
    return list(found)

Alist = solve_many(unitA, 8, range(600))
Blist = solve_many(unitB, 8, range(600))
print("A", len(Alist), "B", len(Blist))
json.dump({"A":Alist,"B":Blist}, open("/tmp/units.json","w"))
for a in Alist: print("A", a)
for b in Blist: print("B", b)
